const form = $('Contract Upload Form').first().json;
const contractName = form['Contract Name'];
const userRole = form['Your Role'];

let text = $input.first().json.text || '';

if (text.trim().length < 200) {
  throw new Error('No readable text found. The PDF may be a scan.');
}

// 1. Normalize
text = text
  .replace(/\r/g, '')
  .replace(/-- \d+ of \d+ --/g, '')
  .replace(/^\s*(Page\s+)?\d+(\s*of\s*\d+)?\s*$/gim, '')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{2,}/g, '\n')
  .trim();

// 2. Find clause headings like "4. TERMINATION" or "Section 4.2 Payment"
const headingRe = /^(?:(?:Section|Article)\s+)?(\d+(?:\.\d+)*)[.)]?\s+([A-Za-z][A-Za-z0-9 ,&\/'\-]{2,80})$/i;

const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
const raw = [];
let current = null;

for (const line of lines) {
  const m = line.match(headingRe);
  const looksLikeHeading = m && !/[.,;:]$/.test(line);
  if (looksLikeHeading) {
    if (current) raw.push(current);
    current = { ref: m[1], title: m[2].trim(), body: [] };
  } else if (current) {
    current.body.push(line);
  }
  // text before the first heading (parties, preamble) is skipped
}
if (current) raw.push(current);

if (raw.length === 0) {
  throw new Error('No numbered clauses found. The contract needs a different splitting method.');
}

// 3. Cap chunk size at ~1500 chars, splitting on sentence boundaries
const MAX = 1500;
const out = [];

for (const c of raw) {
  const body = c.body.join(' ').replace(/\s+/g, ' ').trim();
  if (body.length <= MAX) {
    out.push({ heading: `${c.ref}. ${c.title}`, clause_text: body });
    continue;
  }
  const sentences = body.match(/[^.!?]+[.!?]+(\s|$)|[^.!?]+$/g) || [body];
  let chunk = '';
  let part = 1;
  for (const s of sentences) {
    if ((chunk + s).length > MAX && chunk) {
      out.push({ heading: `${c.ref}. ${c.title} (part ${part})`, clause_text: chunk.trim() });
      part++;
      chunk = '';
    }
    chunk += s;
  }
  if (chunk.trim()) {
    out.push({ heading: `${c.ref}. ${c.title} (part ${part})`, clause_text: chunk.trim() });
  }
}

// 4. One item per clause, with the form data carried along
return out.map((c, i) => ({
  json: {
    contract_name: contractName,
    user_role: userRole,
    clause_no: i + 1,
    clause_count: out.length,
    heading: c.heading,
    clause_text: c.clause_text
  }
}));

