const review_id = $('Create Review Row').first().json.id;
const clauses = $('Split Into Clauses').all().map(i => i.json);
const role = clauses[0].user_role; // 'Client' or 'Vendor'

// hurts: which role the flag is a problem for ('Vendor', 'Client', or 'Both')
const RULES = [
  {
    id: 'auto_renewal', category: 'Auto-renewal', risk_level: 'medium', hurts: 'Both',
    re: /automatically\s+renew|auto-?renew/i,
    issue: 'Contract renews automatically, so missing the notice window locks you in for another term.',
    suggestion: 'Require written agreement to renew, or shorten the non-renewal notice period to 30 days.'
  },
  {
    id: 'long_payment', category: 'Payment terms', risk_level: 'high', hurts: 'Vendor',
    re: /\b(?:sixty|ninety|one\s+hundred\s+(?:and\s+)?twenty|60|90|120)\s*(?:\(\d+\)\s*)?days\b[^.]*\b(?:receipt|invoice)/i,
    issue: 'Payment terms of 60 days or more hurt vendor cash flow.',
    suggestion: 'Negotiate net 30 and add interest on late payments.'
  },
  {
    id: 'unilateral_termination', category: 'Termination', risk_level: 'high', hurts: 'Vendor',
    re: /terminate[^.]*\bat\s+any\s+time\b[^.]*\bwithout\s+(?:notice|cause|liability)/i,
    issue: 'One party can walk away at any time with no notice and no liability.',
    suggestion: 'Make termination mutual with 30 days written notice and payment for work completed.'
  },
  {
    id: 'ip_assignment', category: 'Intellectual property', risk_level: 'high', hurts: 'Vendor',
    re: /irrevocably\s+assigns|work\s+made\s+for\s+hire|assigns?\s+(?:to\s+\w+\s+)?all\s+rights/i,
    issue: 'All IP is assigned away, possibly including your pre-existing tools and code.',
    suggestion: 'Assign only project-specific deliverables and keep ownership of pre-existing materials.'
  },
  {
    id: 'unlimited_liability', category: 'Limitation of liability', risk_level: 'high', hurts: 'Vendor',
    re: /unlimited\s+liability|liability\s+(?:shall\s+be\s+|is\s+)?unlimited/i,
    issue: 'Liability is uncapped, so one dispute could exceed the value of the whole contract.',
    suggestion: 'Cap liability at fees paid in the previous 12 months and exclude consequential damages.'
  },
  {
    id: 'indemnity_broad', category: 'Indemnification', risk_level: 'high', hurts: 'Vendor',
    re: /regardless\s+of\s+fault|any\s+and\s+all\s+claims/i,
    issue: 'Indemnity covers all claims even when you are not at fault.',
    suggestion: 'Limit indemnity to third-party claims caused by your own negligence or breach.'
  },
  {
    id: 'non_compete', category: 'Non-compete / exclusivity', risk_level: 'high', hurts: 'Vendor',
    re: /work\s+exclusively|exclusive\s+(?:provider|supplier|basis)|shall\s+not\s+provide\s+services\s+to\s+any\s+other|non-?compete/i,
    issue: 'You are barred from working for others, possibly for years after the contract ends.',
    suggestion: 'Remove exclusivity, or limit it to direct competitors for 6 months maximum.'
  },
  {
    id: 'perpetual_confidentiality', category: 'Confidentiality', risk_level: 'medium', hurts: 'Both',
    re: /in\s+perpetuity|perpetual(?:ly)?\b/i,
    issue: 'Confidentiality obligations never expire.',
    suggestion: 'Limit confidentiality to 2 to 3 years after termination.'
  },
  {
    id: 'one_sided_confidentiality', category: 'Confidentiality', risk_level: 'high', hurts: 'Vendor',
    re: /has\s+no\s+confidentiality\s+obligations/i,
    issue: 'Confidentiality only binds one side.',
    suggestion: 'Make confidentiality mutual.'
  },
  {
    id: 'liquidated_damages', category: 'Penalties', risk_level: 'high', hurts: 'Vendor',
    re: /liquidated\s+damages|penalt(?:y|ies)/i,
    issue: 'Penalty clause with potentially severe financial consequences for delays.',
    suggestion: 'Cap total penalties at 5 to 10% of the contract value and require notice before they apply.'
  },
  {
    id: 'foreign_jurisdiction', category: 'Governing law', risk_level: 'medium', hurts: 'Both',
    // Home jurisdiction is the Philippines. Anything else is flagged.
    re: /governed\s+by\s+the\s+laws\s+of\s+(?!(?:the\s+)?(?:Republic\s+of\s+the\s+)?Philippines)/i,
    issue: 'Governing law and courts are outside your home jurisdiction, making disputes costly.',
    suggestion: 'Propose Philippine law, or neutral arbitration.'
  }
];

const active = RULES.filter(r => r.hurts === 'Both' || r.hurts === role);

return clauses.map(c => {
  const rule_flags = [];
  for (const r of active) {
    const m = c.clause_text.match(r.re);
    if (m) {
      rule_flags.push({
        rule: r.id,
        category: r.category,
        risk_level: r.risk_level,
        issue: r.issue,
        quote: m[0],
        suggestion: r.suggestion
      });
    }
  }
  return {
    json: {
      ...c,
      review_id,
      rule_flags,
      rule_flag_count: rule_flags.length
    }
  };
});

const clause = $('Loop Over Clauses').item.json;

// 1. Find the model's text, wherever this n8n version puts it
const raw =
  $json.content?.[0]?.text ??
  $json.output?.[0]?.content?.[0]?.text ??
  $json.message?.content ??
  $json.text ??
  '';

// 2. Parse: strip fences, fall back to the first {...} block
let parsed = null;
try {
  const cleaned = String(raw).replace(/```json|```/gi, '').trim();
  try {
    parsed = JSON.parse(cleaned);
  } catch (e) {
    const m = cleaned.match(/\{[\s\S]*\}/);
    parsed = m ? JSON.parse(m[0]) : null;
  }
} catch (e) {
  parsed = null;
}

const base = {
  review_id: clause.review_id,
  clause_no: clause.clause_no,
  heading: clause.heading,
  clause_text: clause.clause_text,
  rule_flags: clause.rule_flags,
  rule_flag_count: clause.rule_flag_count
};

if (!parsed || typeof parsed !== 'object') {
  return { json: { ...base, category: null, risk_level: null, issue: null, quote: null, suggestion: null, valid: false, fail: 'unparseable' } };
}

// 3. Normalize
const norm = s => String(s || '')
  .toLowerCase()
  .replace(/[\u2018\u2019\u201C\u201D"']/g, '')
  .replace(/\s+/g, ' ')
  .trim();

const category   = String(parsed.category || '').trim();
const risk_level = String(parsed.risk_level || '').toLowerCase().trim();
const issue      = String(parsed.issue || '').trim();
const quote      = String(parsed.quote || '').trim();
const suggestion = String(parsed.suggestion || '').trim();

// 4. Checks
const checks = {
  riskLevelValid:  ['low', 'medium', 'high'].includes(risk_level),
  hasCategory:     category.length > 1,
  hasIssue:        issue.length > 0,
  hasSuggestion:   suggestion.length > 0,
  quoteInClause:   quote.length > 0 && norm(clause.clause_text).includes(norm(quote)),
  quoteNotHuge:    quote.split(/\s+/).length <= 40,
  noPlaceholders:  !/\[.*?\]|\{\{.*?\}\}|lorem|xyz/i.test(issue + ' ' + suggestion),
  noAiTells:       !/as an ai|i cannot|i'm unable/i.test(issue + ' ' + suggestion)
};

const failed = Object.entries(checks).filter(([, v]) => !v).map(([k]) => k);

return {
  json: {
    ...base,
    category,
    risk_level,
    issue,
    quote,
    suggestion,
    valid: failed.length === 0,
    fail: failed.join(',')
  }
};

const clauses = $('Rule-Based Red Flag Scan').all().map(i => i.json);
const rows = [];

for (const c of clauses) {
  for (const f of (c.rule_flags || [])) {
    rows.push({
      json: {
        review_id: c.review_id,
        clause_no: c.clause_no,
        heading: c.heading,
        clause_text: c.clause_text,
        source: 'rule',
        category: f.category,
        risk_level: f.risk_level,
        issue: f.issue,
        quote: f.quote,
        suggestion: f.suggestion,
        valid: true,
        fail: ''
      }
    });
  }
}

// Clean contract: no rule flags found. Return one placeholder so the
// workflow keeps running instead of stopping here.
if (rows.length === 0) {
  return [{
    json: {
      review_id: clauses[0].review_id,
      clause_no: 0,
      heading: '',
      clause_text: '',
      source: 'none',
      category: '',
      risk_level: 'low',
      issue: '',
      quote: '',
      suggestion: '',
      valid: true,
      fail: ''
    }
  }];
}

return rows;

const rows = $input.all().map(i => i.json);
const meta = $('Split Into Clauses').first().json;

const RANK = { low: 0, medium: 1, high: 2 };
const POINTS = { low: 0, medium: 4, high: 10 };
const AI_ONLY_POINTS = 2;
const BALANCED = /\b(each|either|both)\s+part(y|ies)\b|\bneither\s+party\b/i;

// Group rows by clause
const byClause = {};
for (const r of rows) {
  (byClause[r.clause_no] = byClause[r.clause_no] || []).push(r);
}

const findings = [];
let cleanClauses = 0;

for (const clauseNo of Object.keys(byClause).map(Number)) {
  const group = byClause[clauseNo];
  const rules = group.filter(r => r.source === 'rule')
    .sort((a, b) => RANK[b.risk_level] - RANK[a.risk_level]);
  const ai = group.find(r => r.source === 'ai');

  const aiActive = ai
    && ai.risk_level !== 'low'
    && String(ai.issue || '').trim().toLowerCase() !== 'none';

  if (rules.length > 0) {
    rules.forEach((r, idx) => {
      const f = {
        clause_no: r.clause_no,
        heading: r.heading,
        category: r.category,
        risk_level: r.risk_level,
        issue: r.issue,
        quote: r.quote,
        suggestion: r.suggestion,
        source: 'rule',
        ai_only: false,
        ai_risk: ai ? ai.risk_level : 'rejected',
        confirmed_by_ai: false
      };
      // Attach the AI's opinion to the top-severity rule flag of the clause
      if (idx === 0 && aiActive) {
        f.confirmed_by_ai = true;
        f.ai_issue = ai.issue;
        f.ai_suggestion = ai.suggestion;
        if (RANK[ai.risk_level] > RANK[f.risk_level]) f.risk_level = ai.risk_level;
      }
      findings.push(f);
    });
  } else if (aiActive) {
    // AI-only finding: no rule agrees with it
    const balanced = BALANCED.test(ai.clause_text || '');
    if (balanced) {
      // The clause binds both sides equally, so the AI's complaint is dropped
      cleanClauses++;
    } else {
      findings.push({
        clause_no: ai.clause_no,
        heading: ai.heading,
        category: ai.category,
        risk_level: RANK[ai.risk_level] > 1 ? 'medium' : ai.risk_level,
        issue: ai.issue,
        quote: ai.quote,
        suggestion: ai.suggestion,
        source: 'ai',
        ai_only: true,
        ai_risk: ai.risk_level,
        confirmed_by_ai: false
      });
    }
  } else {
    cleanClauses++;
  }
}

// Sort: high first, then medium, then by clause number
findings.sort((a, b) =>
  RANK[b.risk_level] - RANK[a.risk_level] || a.clause_no - b.clause_no
);

const highCount = findings.filter(f => f.risk_level === 'high').length;
const mediumCount = findings.filter(f => f.risk_level === 'medium').length;

const risk_score = Math.min(100,
  findings.reduce((sum, f) => sum + (f.ai_only ? AI_ONLY_POINTS : POINTS[f.risk_level]), 0)
);
const risk_level = risk_score >= 45 ? 'High' : risk_score >= 20 ? 'Medium' : 'Low';

return [{
  json: {
    review_id: rows[0].review_id,
    contract_name: meta.contract_name,
    user_role: meta.user_role,
    total_clauses: meta.clause_count,
    clean_clauses: cleanClauses,
    finding_count: findings.length,
    high_count: highCount,
    medium_count: mediumCount,
    confirmed_by_ai_count: findings.filter(f => f.confirmed_by_ai).length,
    ai_only_count: findings.filter(f => f.ai_only).length,
    risk_score,
    risk_level,
    findings
  }
}];

