const m = $('Merge and Score').first().json;

// 1. Read the summary JSON from the model
const raw =
  $json.output?.[0]?.content?.[0]?.text ??
  $json.content?.[0]?.text ??
  $json.message?.content ??
  $json.text ??
  '';

let parsed = null;
try {
  const cleaned = String(raw).replace(/```json|```/gi, '').trim();
  try {
    parsed = JSON.parse(cleaned);
  } catch (e) {
    const mm = cleaned.match(/\{[\s\S]*\}/);
    parsed = mm ? JSON.parse(mm[0]) : null;
  }
} catch (e) {
  parsed = null;
}

const summary = (parsed && parsed.summary)
  ? String(parsed.summary).trim()
  : `Overall risk is ${m.risk_level} with ${m.high_count} high risk and ${m.medium_count} medium risk findings. Review the findings below before signing.`;

const negotiate = m.high_count === 0
  ? []
  : (parsed && Array.isArray(parsed.negotiate_first))
    ? parsed.negotiate_first.slice(0, 3).map(String)
    : m.findings.filter(f => f.risk_level === 'high').slice(0, 3)
        .map(f => `Clause ${f.clause_no}: ${f.issue}`);

// 2. Helpers
const esc = s => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const COLORS = {
  high:   { fg: '#b42318', bg: '#fef3f2', label: 'HIGH RISK' },
  medium: { fg: '#b54708', bg: '#fffaeb', label: 'MEDIUM RISK' },
  low:    { fg: '#027a48', bg: '#ecfdf3', label: 'LOW RISK' }
};
const overall = COLORS[m.risk_level.toLowerCase()] || COLORS.low;
const date = new Date().toISOString().slice(0, 10);

// 3. Findings, grouped by severity
const section = level => {
  const items = m.findings.filter(f => f.risk_level === level);
  if (!items.length) return '';
  const c = COLORS[level];
  const cards = items.map(f => `
    <div class="card" style="border-left:4px solid ${c.fg}">
      <div class="card-head">
        <strong>Clause ${esc(f.clause_no)}: ${esc(f.heading.replace(/^\d+(\.\d+)*\.\s*/, ''))}</strong>
        <span class="tag" style="background:${c.bg};color:${c.fg}">${esc(f.category)}</span>
        ${f.confirmed_by_ai ? '<span class="tag" style="background:#eef4ff;color:#3538cd">Confirmed by AI</span>' : ''}
        ${f.ai_only ? '<span class="tag" style="background:#f2f4f7;color:#667085">AI observation, not independently confirmed</span>' : ''}
      </div>
      <p class="quote">"${esc(f.quote)}"</p>
      <p><strong>Issue:</strong> ${esc(f.issue)}</p>
      <p><strong>Suggested fix:</strong> ${esc(f.suggestion)}</p>
      ${f.ai_issue ? `<p class="ai"><strong>AI reviewer note:</strong> ${esc(f.ai_issue)}</p>` : ''}
    </div>`).join('');
  return `<h2 style="color:${c.fg}">${c.label} (${items.length})</h2>${cards}`;
};

const html = `<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8">
<title>Contract Review: ${esc(m.contract_name)}</title>
<style>
  body{font-family:Segoe UI,Arial,sans-serif;background:#f5f6f8;color:#1d2939;margin:0;padding:32px}
  .wrap{max-width:820px;margin:auto;background:#fff;padding:36px;border-radius:12px}
  h1{margin:0 0 4px;font-size:24px} h2{margin-top:32px;font-size:16px;letter-spacing:.5px}
  .meta{color:#667085;font-size:13px;margin-bottom:24px}
  .score{display:flex;align-items:center;gap:20px;padding:20px;border-radius:10px;background:${overall.bg}}
  .num{font-size:44px;font-weight:700;color:${overall.fg}}
  .lvl{font-weight:700;color:${overall.fg}}
  .stats{color:#475467;font-size:14px}
  .card{background:#fafafa;border-radius:8px;padding:14px 16px;margin:12px 0}
  .card-head{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:6px}
  .tag{font-size:11px;padding:2px 8px;border-radius:99px;font-weight:600}
  .quote{font-style:italic;color:#475467;border-left:3px solid #d0d5dd;padding-left:10px}
  .ai{color:#3538cd;font-size:13px}
  p{margin:6px 0;line-height:1.5}
  ol{line-height:1.6}
  .foot{margin-top:36px;padding-top:16px;border-top:1px solid #eaecf0;color:#667085;font-size:12px}
</style></head><body><div class="wrap">
  <h1>${esc(m.contract_name)}</h1>
  <div class="meta">Reviewed as: <strong>${esc(m.user_role)}</strong> &middot; ${date} &middot; Review #${esc(m.review_id)}</div>
  <div class="score">
    <div class="num">${esc(m.risk_score)}</div>
    <div><div class="lvl">${esc(m.risk_level).toUpperCase()} RISK</div>
    <div class="stats">${m.total_clauses} clauses reviewed &middot; ${m.high_count} high &middot; ${m.medium_count} medium &middot; ${m.clean_clauses} clean</div></div>
  </div>
  <h2>Summary</h2>
  <p>${esc(summary)}</p>
  ${negotiate.length ? `<h2>Negotiate first</h2><ol>${negotiate.map(n => `<li>${esc(n)}</li>`).join('')}</ol>` : ''}
  ${section('high')}${section('medium')}${section('low')}
  <div class="foot">This report is an automated first-pass review to show where to look. It is not legal advice. Have a qualified lawyer review any contract before you sign it.</div>
</div></body></html>`;

return [{
  json: {
    review_id: m.review_id,
    contract_name: m.contract_name,
    user_role: m.user_role,
    risk_score: m.risk_score,
    risk_level: m.risk_level,
    high_count: m.high_count,
    medium_count: m.medium_count,
    finding_count: m.finding_count,
    summary,
    negotiate_first: negotiate,
    top_flags: m.findings.filter(f => f.risk_level === 'high').slice(0, 3)
      .map(f => `Clause ${f.clause_no}: ${f.issue}`),
    report_html: html
  }
}];

