    <div><strong>Issue:</strong> ${esc(f.issue)}</div>
    <div style="margin-top:4px;"><strong>Suggested fix:</strong> ${esc(f.suggestion)}</div>
    ${f.ai_issue ? `<div style="margin-top:4px;color:#3538cd;font-size:13px;"><strong>AI reviewer note:</strong> ${esc(f.ai_issue)}</div>` : ''}
  </td></tr>
</table>`;

const section = level => {
  const items = m.findings.filter(f => f.risk_level === level);
  if (!items.length) return '';
  const c = C[level];
  return `<div style="font-family:${FONT};font-size:15px;font-weight:bold;color:${c.fg};margin:24px 0 10px 0;">${c.label} (${items.length})</div>`
    + items.map(f => card(f, c)).join('');
};

const negotiate = (b.negotiate_first || [])
  .map(n => `<li style="margin-bottom:4px;">${esc(n)}</li>`).join('');

const negotiateBlock = negotiate
  ? `<div style="font-size:15px;font-weight:bold;margin:24px 0 8px 0;">Negotiate first</div>
     <ol style="margin:0;padding-left:20px;font-size:14px;line-height:1.6;">${negotiate}</ol>`
  : '';

const email_html = `<!DOCTYPE html>
<html><head><meta charset="utf-8"></head>
<body style="margin:0;padding:0;background:#f5f6f8;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f5f6f8;">
<tr><td align="center" style="padding:24px 12px;">
<table role="presentation" width="640" cellpadding="0" cellspacing="0" style="width:100%;max-width:640px;background:#ffffff;">
<tr><td style="padding:28px 28px 8px 28px;font-family:${FONT};color:#1d2939;">

  <div style="font-size:22px;font-weight:bold;">${esc(b.contract_name)}</div>
  <div style="font-size:13px;color:#667085;margin:4px 0 18px 0;">Reviewed as ${esc(b.user_role)} &middot; Review #${esc(b.review_id)}</div>

  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${overall.bg};">
    <tr>
      <td width="110" style="padding:16px 20px;font-size:40px;font-weight:bold;color:${overall.fg};">${esc(b.risk_score)}</td>
      <td style="padding:16px 0;font-size:14px;color:#475467;">
        <strong style="color:${overall.fg};">${esc(String(b.risk_level).toUpperCase())} RISK</strong><br>
        ${esc(m.total_clauses)} clauses reviewed &middot; ${esc(b.high_count)} high &middot; ${esc(b.medium_count)} medium &middot; ${esc(m.clean_clauses)} clean
      </td>
    </tr>
  </table>

  <div style="font-size:15px;font-weight:bold;margin:24px 0 8px 0;">Summary</div>
  <div style="font-size:14px;line-height:1.6;">${esc(b.summary)}</div>

  ${negotiateBlock}

  ${section('high')}${section('medium')}${section('low')}

  <div style="margin-top:28px;padding-top:14px;border-top:1px solid #eaecf0;font-size:12px;color:#667085;line-height:1.5;">
    Automated first-pass review to show where to look. Not legal advice. Have a qualified lawyer review any contract before you sign it. The same report is attached as an HTML file.
  </div>

</td></tr>
</table>
</td></tr>
</table>
</body></html>`;

return {
  json: {
    review_id: b.review_id,
    email_subject: `Contract Review: ${b.contract_name} - ${b.risk_level} risk (${b.risk_score}/100)`,
    email_html
  },
  binary: $input.item.binary
};
